\textbf{Limite de la somme trigonométrique}

On cherche $\lim_{n \to \infty} \sum_{k=1}^n \sin\left(\frac{k\pi}{n}\right) \sin\left(\frac{k\pi}{n^2}\right)$.

\par
\textbf{Étape 1 : Asymptotique de sin(kπ/n²)}

Pour $k$ fixé et $n$ grand, $\frac{k\pi}{n^2} \to 0$, donc 
$$\sin\left(\frac{k\pi}{n^2}\right) \sim \frac{k\pi}{n^2}.$$

\par
Pour $k \leq n$, on a $|k\pi/n^2| \leq \pi/n \to 0$, donc l'approximation est uniforme.

\par
\textbf{Étape 2 : Simplification de la somme}

\begin{align}
\sum_{k=1}^n \sin\left(\frac{k\pi}{n}\right) \sin\left(\frac{k\pi}{n^2}\right) &\sim \sum_{k=1}^n \sin\left(\frac{k\pi}{n}\right) \cdot \frac{k\pi}{n^2} \\
&= \frac{\pi}{n^2} \sum_{k=1}^n k \sin\left(\frac{k\pi}{n}\right).
\end{align}

\par
\textbf{Étape 3 : Somme trigonométrique}

On réécrit la somme comme une somme de Riemann. Posons $x_k = k/n$ pour $k = 1, \ldots, n$. Alors 

\begin{align}
\sum_{k=1}^n k \sin\left(\frac{k\pi}{n}\right) &= n \sum_{k=1}^n \frac{k}{n} \sin(\pi x_k) \\
&= n^2 \sum_{k=1}^n x_k \sin(\pi x_k) \cdot \frac{1}{n}.
\end{align}

Ceci est une somme de Riemann pour l'intégrale 
$$\int_0^1 x \sin(\pi x)\,dx$$
avec pas $\Delta x = 1/n$.

\par
\textbf{Étape 4 : Calcul de l'intégrale}

Par intégration par parties, posons $u = x$, $dv = \sin(\pi x)dx$. Alors $du = dx$, $v = -\frac{\cos(\pi x)}{\pi}$.

\begin{align}
\int_0^1 x \sin(\pi x)\,dx &= \left[x \cdot \left(-\frac{\cos(\pi x)}{\pi}\right)\right]_0^1 + \int_0^1 \frac{\cos(\pi x)}{\pi}\,dx \\
&= -\frac{1 \cdot \cos(\pi)}{\pi} - 0 + \frac{1}{\pi}\left[\frac{\sin(\pi x)}{\pi}\right]_0^1 \\
&= \frac{1}{\pi} + 0 = \frac{1}{\pi}.
\end{align}

\par
\textbf{Étape 5 : Conclusion}

$$\sum_{k=1}^n \sin\left(\frac{k\pi}{n}\right) \sin\left(\frac{k\pi}{n^2}\right) \sim \frac{\pi}{n^2} \cdot n^2 \cdot \frac{1}{\pi} = 1.$$

Donc $\boxed{\lim_{n \to \infty} \sum_{k=1}^n \sin\left(\frac{k\pi}{n}\right) \sin\left(\frac{k\pi}{n^2}\right) = 1.}$

\textbf{Asymptotique de l'intégrale (1 + x²)^{1/n}}

On cherche $a, b$ tels que 
$$I(n) = \int_0^1 (1+x^2)^{1/n}\,dx = a + \frac{b}{n} + O\left(\frac{1}{n^2}\right).$$

\par
\textbf{Étape 1 : Développement du noyau}

Pour $n \geq 1$, 
$$(1+x^2)^{1/n} = e^{\frac{\ln(1+x^2)}{n}} = 1 + \frac{\ln(1+x^2)}{n} + \frac{1}{2}\left(\frac{\ln(1+x^2)}{n}\right)^2 + O\left(\frac{1}{n^3}\right).$$

\par
\textbf{Étape 2 : Intégration terme à terme}

\begin{align}
I(n) &= \int_0^1 \left[1 + \frac{\ln(1+x^2)}{n} + O\left(\frac{1}{n^2}\right)\right]\,dx \\
&= 1 + \frac{1}{n}\int_0^1 \ln(1+x^2)\,dx + O\left(\frac{1}{n^2}\right).
\end{align}

\par
Donc $a = 1$.

\par
\textbf{Étape 3 : Calcul de l'intégrale} $\int_0^1 \ln(1+x^2)\,dx$

Par intégration par parties, posons $u = \ln(1+x^2)$, $dv = dx$. Alors $du = \frac{2x}{1+x^2}dx$, $v = x$.

\begin{align}
\int_0^1 \ln(1+x^2)\,dx &= [x\ln(1+x^2)]_0^1 - \int_0^1 \frac{2x^2}{1+x^2}\,dx \\
&= \ln 2 - 2\int_0^1 \frac{x^2}{1+x^2}\,dx.
\end{align}

\par
Pour la deuxième intégrale, écrivons $\frac{x^2}{1+x^2} = 1 - \frac{1}{1+x^2}$, donc 

\begin{align}
\int_0^1 \frac{x^2}{1+x^2}\,dx &= \int_0^1 dx - \int_0^1 \frac{dx}{1+x^2} \\
&= 1 - [\arctan(x)]_0^1 \\
&= 1 - \frac{\pi}{4}.
\end{align}

\par
\textbf{Étape 4 : Résultat}

$$\int_0^1 \ln(1+x^2)\,dx = \ln 2 - 2\left(1 - \frac{\pi}{4}\right) = \ln 2 - 2 + \frac{\pi}{2}.$$

Donc $\boxed{a = 1, \quad b = \ln 2 - 2 + \frac{\pi}{2}.}$

