\textbf{Asymptotique : u_n = n + ln n + (ln n)/n - 1/n + o(1/n)}

\par
\textbf{Étape 1 : Approche itérative}

On écrit $u_n = n + \ln(u_{n-1})$. Supposons que $u_{n-1}$ admet un développement asymptotatique 
$$u_{n-1} = (n-1) + \ln(n-1) + w_{n-1}$$
où $w_{n-1} = o(\ln n)$.

\par
\textbf{Étape 2 : Substitution}

$$u_n = n + \ln\left((n-1) + \ln(n-1) + w_{n-1}\right) = n + \ln\left((n-1)\left(1 + \frac{\ln(n-1) + w_{n-1}}{n-1}\right)\right).$$

\par
Donc 

$$u_n = n + \ln(n-1) + \ln\left(1 + \frac{\ln(n-1) + w_{n-1}}{n-1}\right).$$

\par
Avec $\ln(1+x) = x - \frac{x^2}{2} + O(x^3)$ et $\frac{\ln(n-1)}{n-1} \to 0$ :

$$u_n = n + \ln(n-1) + \frac{\ln(n-1)}{n-1} + O\left(\frac{\ln^2 n}{n^2}\right).$$

\par
\textbf{Étape 3 : Raffinement}

Écrivons $\ln(n-1) = \ln n + \ln\left(1 - \frac{1}{n}\right) = \ln n - \frac{1}{n} + O(1/n^2)$. Alors 

\begin{align}
u_n &= n + \ln n - \frac{1}{n} + \frac{\ln n}{n} + o\left(\frac{\ln n}{n}\right) \\
&= \boxed{n + \ln n + \frac{\ln n}{n} - \frac{1}{n} + o\left(\frac{1}{n}\right).}
\end{align}

\textbf{Développement complet : u_n = √(2n) + (ln n)/(4√(2n)) + o((ln n)/√n)}

\par
\textbf{Étape 1 : Développement de la racine}

De $u_n^2 = 2n + \frac{\ln n}{2} + o(\ln n)$, on écrit 

$$u_n = \sqrt{2n + \frac{\ln n}{2} + o(\ln n)} = \sqrt{2n}\sqrt{1 + \frac{\ln n}{4n} + o\left(\frac{\ln n}{n}\right)}.$$

\par
\textbf{Étape 2 : Développement de la racine carrée}

Avec $\sqrt{1+x} = 1 + \frac{x}{2} - \frac{x^2}{8} + O(x^3)$ et $x = \frac{\ln n}{4n} + o(\ln n / n)$ :

\begin{align}
\sqrt{1 + \frac{\ln n}{4n} + o\left(\frac{\ln n}{n}\right)} &= 1 + \frac{1}{2} \cdot \frac{\ln n}{4n} + o\left(\frac{\ln n}{n}\right) \\
&= 1 + \frac{\ln n}{8n} + o\left(\frac{\ln n}{n}\right).
\end{align}

\par
\textbf{Étape 3 : Multiplication}

\begin{align}
u_n &= \sqrt{2n} \left(1 + \frac{\ln n}{8n} + o\left(\frac{\ln n}{n}\right)\right) \\
&= \sqrt{2n} + \sqrt{2n} \cdot \frac{\ln n}{8n} + o\left(\frac{\ln n}{\sqrt{n}}\right) \\
&= \sqrt{2n} + \frac{\ln n}{8\sqrt{n/2}} + o\left(\frac{\ln n}{\sqrt{n}}\right) \\
&= \sqrt{2n} + \frac{\ln n}{4\sqrt{2n}} + o\left(\frac{\ln n}{\sqrt{n}}\right).
\end{align}

\par
\textbf{Étape 4 : Conclusion}

$$\boxed{u_n = \sqrt{2n} + \frac{\ln n}{4\sqrt{2n}} + o\left(\frac{\ln n}{\sqrt{n}}\right).}$$
